struct Options {
    int decompress, test, list, train, benchmark;
    int force, rm, stdout_mode, quiet, verbose, recursive;
    int progress, pass_through;
    int level, ultra, checksum, no_dict_id, format; /* 0 zstd, 1 gzip */
    int threads, exclude_compressed;
    int has_output; char *output;
    char *dict; char *filelist;
    int stream_size_set; unsigned long long stream_size;
    size_t maxdict;
    const char *prog;
};

static void bad_param(const char *arg, const char *prog) {
    fprintf(stderr, "Incorrect parameter: %s \n", arg);
    short_help(stderr, prog);
}
static int missing_arg(void) {
    fprintf(stderr, "error: missing command argument \n");
    return 1;
}
static int separated_arg_error(void) {
    fprintf(stderr, "error: command cannot be separated from its argument by another command \n");
    return 1;
}

static int parse_args(int argc, char **argv, struct Options *o, struct StrVec *inputs) {
    memset(o, 0, sizeof(*o));
    o->level = 3; o->checksum = 1; o->threads = 4; o->maxdict = 112640; o->prog = base_name(argv[0]);
    const char *bn = base_name(argv[0]);
    if (strstr(bn, "unzstd")) o->decompress = 1;
    if (strstr(bn, "zstdcat")) { o->decompress = 1; o->stdout_mode = 1; }
    if (strstr(bn, "zstdmt")) o->threads = 0;

    int after_dd = 0;
    for (int i=1; i<argc; ++i) {
        char *a = argv[i];
        if (after_dd) { vec_add(inputs, a); continue; }
        if (strcmp(a, "--") == 0) { after_dd = 1; continue; }
        if (a[0] != '-' || strcmp(a, "-") == 0) { vec_add(inputs, a); continue; }
        if (a[1] == '-') {
            if (strcmp(a, "--help") == 0) { full_help(stdout, o->prog); exit(0); }
            else if (strcmp(a, "--version") == 0) { version_out(o->verbose); exit(0); }
            else if (strcmp(a, "--decompress") == 0) o->decompress = 1;
            else if (strcmp(a, "--stdout") == 0) o->stdout_mode = 1;
            else if (strcmp(a, "--force") == 0) o->force = 1;
            else if (strcmp(a, "--keep") == 0) o->rm = 0;
            else if (strcmp(a, "--rm") == 0) o->rm = 1;
            else if (strcmp(a, "--quiet") == 0) o->quiet++;
            else if (strcmp(a, "--verbose") == 0) o->verbose++;
            else if (strcmp(a, "--test") == 0) { o->test = 1; o->decompress = 1; }
            else if (strcmp(a, "--train") == 0) o->train = 1;
            else if (strcmp(a, "--ultra") == 0) o->ultra = 1;
            else if (strcmp(a, "--check") == 0) o->checksum = 1;
            else if (strcmp(a, "--no-check") == 0) o->checksum = 0;
            else if (strcmp(a, "--progress") == 0) o->progress = 1;
            else if (strcmp(a, "--no-progress") == 0) o->progress = -1;
            else if (strcmp(a, "--pass-through") == 0) o->pass_through = 1;
            else if (strcmp(a, "--no-pass-through") == 0) o->pass_through = 0;
            else if (strcmp(a, "--single-thread") == 0) o->threads = 1;
            else if (strcmp(a, "--adapt") == 0 || strcmp(a, "--rsyncable") == 0 ||
                     strcmp(a, "--asyncio") == 0 || strcmp(a, "--no-asyncio") == 0 ||
                     strcmp(a, "--sparse") == 0 || strcmp(a, "--no-sparse") == 0 ||
                     strcmp(a, "--compress-literals") == 0 || strcmp(a, "--no-compress-literals") == 0 ||
                     strcmp(a, "--row-match-finder") == 0 || strcmp(a, "--no-row-match-finder") == 0 ||
                     strcmp(a, "--mmap-dict") == 0 || strcmp(a, "--no-mmap-dict") == 0) {
                /* accepted but not material for common tests */
            }
            else if (strcmp(a, "--exclude-compressed") == 0) o->exclude_compressed = 1;
            else if (strcmp(a, "--no-dictID") == 0) o->no_dict_id = 1;
            else if (strcmp(a, "--patch-apply") == 0) o->decompress = 1;
            else if (strcmp(a, "--format=zstd") == 0) o->format = 0;
            else if (strcmp(a, "--format=gzip") == 0) o->format = 1;
            else if (strncmp(a, "--fast", 6) == 0) {
                if (a[6] == '\0') o->level = -1;
                else if (a[6] == '=') { int ok=0; unsigned long long v=parse_u64_size(a+7,&ok); if (!ok) { bad_param(a,o->prog); return 1; } o->level = -(int)v; }
                else { bad_param(a,o->prog); return 1; }
            }
            else if (strncmp(a, "--long", 6) == 0) {
                /* recognized; the backend is left to choose unless explicitly tested */
            }
            else if (strncmp(a, "--format", 8) == 0) { bad_param(a, o->prog); return 1; }
            else if (strncmp(a, "--stream-size=", 14) == 0) { int ok=0; o->stream_size=parse_u64_size(a+14,&ok); if(!ok){bad_param(a,o->prog);return 1;} o->stream_size_set=1; }
            else if (strcmp(a, "--stream-size") == 0) { if (++i>=argc) return missing_arg(); int ok=0; o->stream_size=parse_u64_size(argv[i],&ok); if(!ok){bad_param(argv[i],o->prog);return 1;} o->stream_size_set=1; }
            else if (strncmp(a, "--maxdict=", 10) == 0) { int ok=0; o->maxdict=(size_t)parse_u64_size(a+10,&ok); if(!ok){bad_param(a,o->prog);return 1;} }
            else if (strcmp(a, "--maxdict") == 0) { if (++i>=argc) return missing_arg(); int ok=0; o->maxdict=(size_t)parse_u64_size(argv[i],&ok); if(!ok){bad_param(argv[i],o->prog);return 1;} }
            else if (strcmp(a, "--filelist") == 0) { if (++i>=argc) return missing_arg(); o->filelist = argv[i]; }
            else if (strcmp(a, "--trace") == 0 || strcmp(a, "--output-dir-flat") == 0 || strcmp(a, "--output-dir-mirror") == 0) { if (++i>=argc) return missing_arg(); }
            else if (strncmp(a, "--trace=", 8)==0 || strncmp(a, "--output-dir-flat=",18)==0 || strncmp(a,"--output-dir-mirror=",20)==0) { }
            else if (strncmp(a, "--size-hint=", 12)==0 || strncmp(a, "--target-compressed-block-size=",31)==0 ||
                     strncmp(a, "--jobsize=", 10)==0 || strncmp(a, "--split=", 8)==0 ||
                     strncmp(a, "--dictID=", 9)==0 || strncmp(a, "--auto-threads=",15)==0 ||
                     strncmp(a, "--priority=", 11)==0 || strncmp(a, "--patch-from=",13)==0 ||
                     strncmp(a, "--train-cover", 13)==0 || strncmp(a, "--train-fastcover", 17)==0 ||
                     strncmp(a, "--train-legacy", 14)==0) { }
            else if (strcmp(a, "--size-hint") == 0 || strcmp(a, "--target-compressed-block-size") == 0 ||
                     strcmp(a, "--jobsize") == 0 || strcmp(a, "--split") == 0 || strcmp(a, "--dictID") == 0 ||
                     strcmp(a, "--patch-from") == 0) { if (++i>=argc) return missing_arg(); }
            else { bad_param(a, o->prog); return 1; }
            continue;
        }
        /* short option cluster */
        if (isdigit((unsigned char)a[1])) {
            int lev = 0; for (int j=1; a[j]; ++j) { if(!isdigit((unsigned char)a[j])) { bad_param(a,o->prog); return 1; } lev = lev*10 + (a[j]-'0'); }
            o->level = lev; continue;
        }
        for (int j=1; a[j]; ++j) {
            char c = a[j];
            switch (c) {
                case 'h': short_help(stdout, o->prog); exit(0);
                case 'H': full_help(stdout, o->prog); exit(0);
                case 'V': version_out(o->verbose); exit(0);
                case 'd': o->decompress = 1; break;
                case 'c': o->stdout_mode = 1; break;
                case 'f': o->force = 1; break;
                case 'k': o->rm = 0; break;
                case 'q': o->quiet++; break;
                case 'v': o->verbose++; break;
                case 'r': o->recursive = 1; break;
                case 't': o->test = 1; o->decompress = 1; break;
                case 'l': o->list = 1; break;
                case 'S': break;
                case 'b': o->benchmark = 1; if (a[j+1]) j=(int)strlen(a)-1; break;
                case 'e': case 'i': case 'M': if (a[j+1]) j=(int)strlen(a)-1; break;
                case 'T': if (a[j+1]) { o->threads = atoi(a+j+1); j=(int)strlen(a)-1; } break;
                case 'D':
                    if (a[j+1]) { o->dict = a+j+1; j=(int)strlen(a)-1; }
                    else { if (++i>=argc) return missing_arg(); o->dict = argv[i]; }
                    break;
                case 'o':
                    if (a[j+1]) {
                        /* The observed parser rejects compact -ofoo forms. */
                        if (j==1) return missing_arg();
                        char tmp[4] = "-?"; tmp[1]=a[j+1]; bad_param(tmp, o->prog); return 1;
                    }
                    if (++i>=argc) return missing_arg();
                    if (strcmp(argv[i], "-") == 0) return separated_arg_error();
                    o->has_output = 1; o->output = argv[i];
                    j=(int)strlen(a)-1;
                    break;
                default: {
                    char tmp[4] = "-?"; tmp[1]=c; bad_param(tmp, o->prog); return 1;
                }
            }
        }
    }
    if (o->level > 19 && !o->ultra) {
        if (o->quiet == 0) fprintf(stderr, "Warning : compression level higher than max, reduced to 19 \n");
        o->level = 19;
    }
    if (o->level > 22) o->level = 22;
    if (o->filelist) {
        FILE *fl = fopen(o->filelist, "rb");
        if (!fl) { fprintf(stderr, "zstd: can't open %s : %s -- ignored \n", o->filelist, strerror(errno)); return 1; }
        char *line=NULL; size_t cap=0; ssize_t len;
        while ((len=getline(&line,&cap,fl)) >= 0) {
            while (len>0 && (line[len-1]=='\n' || line[len-1]=='\r')) line[--len]=0;
            if (len>0) vec_add(inputs, line);
        }
        free(line); fclose(fl);
    }
    return 0;
}

static char *derive_decomp_name(const char *in) {
    size_t n = strlen(in);
    if (ends_with(in, ".zst")) return strndup(in, n-4);
    if (ends_with(in, ".tzst")) { char *r=strndup(in, n-5); r=(char*)realloc(r, strlen(r)+5); strcat(r,".tar"); return r; }
    if (ends_with(in, ".gz")) return strndup(in, n-3);
    if (ends_with(in, ".tgz")) { char *r=strndup(in, n-4); r=(char*)realloc(r, strlen(r)+5); strcat(r,".tar"); return r; }
    return NULL;
}
static char *derive_comp_name(const char *in, int fmt) {
    const char *suf = fmt==1 ? ".gz" : ".zst";
    char *r = (char*)malloc(strlen(in)+strlen(suf)+1);
    strcpy(r,in); strcat(r,suf); return r;
}

static FILE *open_output_checked(const char *path, int force) {
    if (!path || strcmp(path, "-")==0) return stdout;
    struct stat st;
    if (!force && stat(path, &st) == 0) {
        fprintf(stderr, "zstd: %s already exists; overwrite (y/n) ? ", path);
        int ch = getchar();
        if (ch!='y' && ch!='Y') {
            fprintf(stderr, "Not overwritten  \n \n");
            return NULL;
        }
    }
    FILE *f = fopen(path, "wb");
    if (!f) fprintf(stderr, "zstd: %s: %s\n", path, strerror(errno));
    return f;
}

static int load_dict_file(const char *path, unsigned char **buf, size_t *sz) {
    *buf=NULL; *sz=0;
    if (!path) return 0;
    if (read_file_all(path, buf, sz) != 0) {
        fprintf(stderr, "zstd: can't stat %s : %s -- ignored \n", path, strerror(errno));
        return 1;
    }
    return 0;
}

static int zstd_set_common_cparams(ZSTD_CCtx *c, const struct Options *o, int content_size_flag, const void *dict, size_t dictsz) {
    size_t r;
    r = Z.ZSTD_CCtx_setParameter(c, ZSTD_c_compressionLevel, o->level); if (Z.ZSTD_isError(r)) return (int)r;
    r = Z.ZSTD_CCtx_setParameter(c, ZSTD_c_checksumFlag, o->checksum); if (Z.ZSTD_isError(r)) return (int)r;
    r = Z.ZSTD_CCtx_setParameter(c, ZSTD_c_contentSizeFlag, content_size_flag); if (Z.ZSTD_isError(r)) return (int)r;
    if (o->no_dict_id) { r = Z.ZSTD_CCtx_setParameter(c, ZSTD_c_dictIDFlag, 0); if (Z.ZSTD_isError(r)) return (int)r; }
    if (dict && dictsz && Z.ZSTD_CCtx_loadDictionary) { r = Z.ZSTD_CCtx_loadDictionary(c, dict, dictsz); if (Z.ZSTD_isError(r)) return (int)r; }
    return 0;
}

static int compress_zstd_buffer(const unsigned char *src, size_t srcsz, unsigned char **dst, size_t *dstsz, const struct Options *o, const void *dict, size_t dictsz) {
    if (load_zstd()) return 1;
    ZSTD_CCtx *c = Z.ZSTD_createCCtx(); if (!c) return 1;
    int pr = zstd_set_common_cparams(c, o, 1, dict, dictsz);
    if (pr) { fprintf(stderr, "zstd: error : %s\n", Z.ZSTD_getErrorName((size_t)pr)); Z.ZSTD_freeCCtx(c); return 1; }
    size_t cap = Z.ZSTD_compressBound(srcsz);
    *dst = (unsigned char*)malloc(cap ? cap : 1);
    if (!*dst) { Z.ZSTD_freeCCtx(c); return 1; }
    size_t r = Z.ZSTD_compress2(c, *dst, cap, src, srcsz);
    if (Z.ZSTD_isError(r)) { fprintf(stderr, "zstd: error : %s\n", Z.ZSTD_getErrorName(r)); Z.ZSTD_freeCCtx(c); free(*dst); return 1; }
    *dstsz = r; Z.ZSTD_freeCCtx(c); return 0;
}

static int compress_zstd_stream(FILE *in, FILE *out, const struct Options *o, const void *dict, size_t dictsz, unsigned long long *in_total, unsigned long long *out_total) {
    if (load_zstd()) return 1;
    ZSTD_CCtx *c = Z.ZSTD_createCCtx(); if (!c) return 1;
    int pr = zstd_set_common_cparams(c, o, 1, dict, dictsz);
    if (pr) { fprintf(stderr, "zstd: error : %s\n", Z.ZSTD_getErrorName((size_t)pr)); Z.ZSTD_freeCCtx(c); return 1; }
    if (o->stream_size_set && Z.ZSTD_CCtx_setPledgedSrcSize) {
        size_t r = Z.ZSTD_CCtx_setPledgedSrcSize(c, o->stream_size);
        if (Z.ZSTD_isError(r)) { fprintf(stderr, "zstd: error : %s\n", Z.ZSTD_getErrorName(r)); Z.ZSTD_freeCCtx(c); return 1; }
    }
    size_t outcap = Z.ZSTD_CStreamOutSize ? Z.ZSTD_CStreamOutSize() : 131591;
    unsigned char *ibuf=(unsigned char*)malloc(131072), *obuf=(unsigned char*)malloc(outcap);
    if (!ibuf || !obuf) { Z.ZSTD_freeCCtx(c); free(ibuf); free(obuf); return 1; }
    *in_total = *out_total = 0;
    for (;;) {
        size_t n = fread(ibuf, 1, 131072, in);
        if (n) {
            *in_total += n;
            ZSTD_inBuffer zin = { ibuf, n, 0 };
            while (zin.pos < zin.size) {
                ZSTD_outBuffer zout = { obuf, outcap, 0 };
                size_t r = Z.ZSTD_compressStream2(c, &zout, &zin, ZSTD_e_continue);
                if (Z.ZSTD_isError(r)) { fprintf(stderr, "zstd: error %u : %s \n", (unsigned)r, Z.ZSTD_getErrorName(r)); free(ibuf); free(obuf); Z.ZSTD_freeCCtx(c); return (int)r; }
                if (zout.pos && fwrite(obuf,1,zout.pos,out)!=zout.pos) { free(ibuf); free(obuf); Z.ZSTD_freeCCtx(c); return 1; }
                *out_total += zout.pos;
            }
        }
        if (n < 131072) { if (ferror(in)) { free(ibuf); free(obuf); Z.ZSTD_freeCCtx(c); return 1; } break; }
    }
    for (;;) {
        ZSTD_inBuffer zin = { ibuf, 0, 0 };
        ZSTD_outBuffer zout = { obuf, outcap, 0 };
        size_t r = Z.ZSTD_compressStream2(c, &zout, &zin, ZSTD_e_end);
        if (Z.ZSTD_isError(r)) { fprintf(stderr, "zstd: error %u : %s \n", (unsigned)r, Z.ZSTD_getErrorName(r)); free(ibuf); free(obuf); Z.ZSTD_freeCCtx(c); return (int)r; }
        if (zout.pos && fwrite(obuf,1,zout.pos,out)!=zout.pos) { free(ibuf); free(obuf); Z.ZSTD_freeCCtx(c); return 1; }
        *out_total += zout.pos;
        if (r == 0) break;
    }
    free(ibuf); free(obuf); Z.ZSTD_freeCCtx(c); return 0;
}

static int gzip_compress_buffer(const unsigned char *src, size_t srcsz, unsigned char **dst, size_t *dstsz, const struct Options *o) {
    int lvl = o->level; if (lvl < 0) lvl = 1; if (lvl > 9) lvl = 9; if (lvl == 0) lvl = 0;
    z_stream zs; memset(&zs,0,sizeof(zs));
    if (deflateInit2(&zs, lvl, Z_DEFLATED, 15+16, 8, Z_DEFAULT_STRATEGY) != Z_OK) return 1;
    size_t cap = compressBound(srcsz) + 32; *dst=(unsigned char*)malloc(cap?cap:1);
    zs.next_in=(Bytef*)src; zs.avail_in=(uInt)srcsz; zs.next_out=*dst; zs.avail_out=(uInt)cap;
    int r = deflate(&zs, Z_FINISH);
    if (r != Z_STREAM_END) { deflateEnd(&zs); free(*dst); return 1; }
    *dstsz = zs.total_out; deflateEnd(&zs); return 0;
}

static int gzip_compress_stream(FILE *in, FILE *out, const struct Options *o, unsigned long long *in_total, unsigned long long *out_total) {
    int lvl=o->level; if(lvl<0)lvl=1; if(lvl>9)lvl=9;
    z_stream zs; memset(&zs,0,sizeof(zs));
    if (deflateInit2(&zs, lvl, Z_DEFLATED, 15+16, 8, Z_DEFAULT_STRATEGY) != Z_OK) return 1;
    unsigned char ibuf[131072], obuf[131072]; *in_total=*out_total=0;
    int flush;
    do {
        zs.avail_in = (uInt)fread(ibuf,1,sizeof(ibuf),in); *in_total += zs.avail_in;
        if (ferror(in)) { deflateEnd(&zs); return 1; }
        flush = feof(in) ? Z_FINISH : Z_NO_FLUSH;
        zs.next_in = ibuf;
        do {
            zs.avail_out = sizeof(obuf); zs.next_out = obuf;
            int r = deflate(&zs, flush); if (r == Z_STREAM_ERROR) { deflateEnd(&zs); return 1; }
            size_t have = sizeof(obuf)-zs.avail_out;
            if (have && fwrite(obuf,1,have,out)!=have) { deflateEnd(&zs); return 1; }
            *out_total += have;
        } while (zs.avail_out == 0);
    } while (flush != Z_FINISH);
    deflateEnd(&zs); return 0;
}

static int zstd_decompress_to_file(const unsigned char *src, size_t srcsz, FILE *out, const struct Options *o, const void *dict, size_t dictsz, unsigned long long *decoded) {
    (void)o;
    if (load_zstd()) return 1;
    ZSTD_DCtx *d = Z.ZSTD_createDCtx(); if (!d) return 1;
    if (dict && dictsz && Z.ZSTD_DCtx_loadDictionary) {
        size_t r = Z.ZSTD_DCtx_loadDictionary(d, dict, dictsz);
        if (Z.ZSTD_isError(r)) { fprintf(stderr, "zstd: error : %s\n", Z.ZSTD_getErrorName(r)); Z.ZSTD_freeDCtx(d); return 1; }
    }
    size_t outcap = Z.ZSTD_DStreamOutSize ? Z.ZSTD_DStreamOutSize() : 131072;
    unsigned char *obuf=(unsigned char*)malloc(outcap);
    if (!obuf) { Z.ZSTD_freeDCtx(d); return 1; }
    ZSTD_inBuffer zin = { src, srcsz, 0 };
    *decoded = 0;
    while (zin.pos < zin.size) {
        ZSTD_outBuffer zout = { obuf, outcap, 0 };
        size_t r = Z.ZSTD_decompressStream(d, &zout, &zin);
        if (Z.ZSTD_isError(r)) {
            fprintf(stderr, "zstd: error : %s\n", Z.ZSTD_getErrorName(r));
            free(obuf); Z.ZSTD_freeDCtx(d); return 1;
        }
        if (zout.pos) {
            if (out && fwrite(obuf,1,zout.pos,out)!=zout.pos) { free(obuf); Z.ZSTD_freeDCtx(d); return 1; }
            *decoded += zout.pos;
        }
        if (r == 0 && zin.pos == zin.size) break;
        if (r == 0 && zin.pos < zin.size) continue;
    }
    free(obuf); Z.ZSTD_freeDCtx(d); return 0;
}

static int gzip_decompress_to_file(const unsigned char *src, size_t srcsz, FILE *out, unsigned long long *decoded) {
    z_stream zs; memset(&zs,0,sizeof(zs));
    if (inflateInit2(&zs, 15+32) != Z_OK) return 1;
    unsigned char obuf[131072]; zs.next_in=(Bytef*)src; zs.avail_in=(uInt)srcsz; *decoded=0;
    int ret;
    do {
        zs.next_out=obuf; zs.avail_out=sizeof(obuf);
        ret = inflate(&zs, Z_NO_FLUSH);
        if (ret != Z_OK && ret != Z_STREAM_END) { inflateEnd(&zs); return 1; }
        size_t have = sizeof(obuf)-zs.avail_out;
        if (have) { if(out && fwrite(obuf,1,have,out)!=have){inflateEnd(&zs);return 1;} *decoded += have; }
    } while (ret != Z_STREAM_END);
    inflateEnd(&zs); return 0;
}

static void print_comp_status(const char *in, unsigned long long insz, unsigned long long outsz, const char *outname) {
    char a[32], b[32]; format_size(a,sizeof(a),insz); format_size(b,sizeof(b),outsz);
    if (insz == 0) fprintf(stderr, "%-20s:  (%s => %s, %s) \n", in, a, b, outname);
    else fprintf(stderr, "%-20s:%6.2f%%   (%s => %s, %s) \n", in, (double)outsz*100.0/(double)insz, a, b, outname);
}
static void print_decomp_status(const char *in, unsigned long long outsz) {
    fprintf(stderr, "%-20s: %llu bytes \n", in, outsz);
}

static int is_compressed_suffix(const char *p) {
    return ends_with(p,".zst") || ends_with(p,".gz") || ends_with(p,".xz") || ends_with(p,".lz4") || ends_with(p,".zip") || ends_with(p,".bz2");
}

static void collect_recursive(struct StrVec *out, const char *path) {
    struct stat st;
    if (stat(path,&st)!=0) return;
    if (S_ISREG(st.st_mode)) { vec_add(out,path); return; }
    if (!S_ISDIR(st.st_mode)) return;
    DIR *d = opendir(path); if (!d) return;
    struct dirent *e;
    while ((e=readdir(d))) {
        if (strcmp(e->d_name,".")==0 || strcmp(e->d_name,"..")==0) continue;
        char *p; if (asprintf(&p, "%s/%s", path, e->d_name) < 0) continue;
        collect_recursive(out,p); free(p);
    }
    closedir(d);
}

static int do_compress_one_file(const char *path, const struct Options *o, const void *dict, size_t dictsz, const char *forced_out, unsigned long long *tin, unsigned long long *tout, int show_status) {
    struct stat st;
    if (stat(path, &st) != 0) { if (o->quiet<2) fprintf(stderr, "zstd: can't stat %s : %s -- ignored \n", path, strerror(errno)); return 1; }
    if (S_ISDIR(st.st_mode)) { if (o->quiet<2) fprintf(stderr, "zstd: %s is a directory -- ignored \n", path); return 1; }
    if (!S_ISREG(st.st_mode) && !o->force) { if(o->quiet<2) fprintf(stderr,"zstd: %s is not a regular file -- ignored \n", path); return 1; }
    if (o->exclude_compressed && is_compressed_suffix(path)) return 0;
    unsigned char *src=NULL, *dst=NULL; size_t srcsz=0, dstsz=0;
    if (read_file_all(path,&src,&srcsz)!=0) { if(o->quiet<2) fprintf(stderr,"zstd: can't read %s : %s -- ignored \n", path, strerror(errno)); return 1; }
    int r = (o->format==1) ? gzip_compress_buffer(src,srcsz,&dst,&dstsz,o) : compress_zstd_buffer(src,srcsz,&dst,&dstsz,o,dict,dictsz);
    if (r) { free(src); return r; }
    char *outname = NULL; const char *on;
    if (o->stdout_mode) on = "stdout";
    else if (forced_out) on = forced_out;
    else { outname = derive_comp_name(path, o->format); on = outname; }
    FILE *out = stdout;
    if (!o->stdout_mode) { out = open_output_checked(on, o->force); if (!out) { free(src); free(dst); free(outname); return 1; } }
    if (fwrite(dst,1,dstsz,out)!=dstsz) r=1;
    if (!o->stdout_mode) fclose(out);
    if (!r) {
        *tin += srcsz; *tout += dstsz;
        if (show_status && !o->stdout_mode && o->quiet==0) print_comp_status(path, srcsz, dstsz, on);
        if (o->rm && !o->stdout_mode) remove(path);
    }
    free(src); free(dst); free(outname); return r;
}

static int do_compress_stdin(const struct Options *o, const void *dict, size_t dictsz) {
    FILE *out = stdout; int close_out=0; const char *on = o->has_output ? o->output : "stdout";
    if (o->has_output && !o->stdout_mode) { out=open_output_checked(o->output,o->force); if(!out) return 1; close_out=1; }
    unsigned long long inb=0,outb=0; int r;
    if (o->format==1) r = gzip_compress_stream(stdin,out,o,&inb,&outb);
    else r = compress_zstd_stream(stdin,out,o,dict,dictsz,&inb,&outb);
    if (close_out) fclose(out);
    (void)on;
    return r==0?0:(r==11?11:1);
}

static int do_decompress_one(const char *path, const struct Options *o, const void *dict, size_t dictsz, const char *forced_out, unsigned long long *tout, int show_status) {
    unsigned char *src=NULL; size_t srcsz=0; int from_stdin = strcmp(path,"-")==0;
    if (from_stdin) { if (read_stream_all(stdin,&src,&srcsz)!=0) return 1; }
    else {
        struct stat st;
        if (stat(path,&st)!=0) { if(o->quiet<2) fprintf(stderr,"zstd: can't stat %s : %s -- ignored \n", path, strerror(errno)); return 1; }
        if (S_ISDIR(st.st_mode)) { if(o->quiet<2) fprintf(stderr,"zstd: %s is a directory -- ignored \n", path); return 1; }
        if (read_file_all(path,&src,&srcsz)!=0) { if(o->quiet<2) fprintf(stderr,"zstd: can't read %s : %s -- ignored \n", path, strerror(errno)); return 1; }
    }
    char *derived=NULL; const char *on=NULL; int to_stdout = o->stdout_mode || from_stdin || o->test;
    if (to_stdout) on = "stdout";
    else if (forced_out) on = forced_out;
    else if (o->has_output) on = o->output;
    else {
        derived = derive_decomp_name(path);
        if (!derived) { if(o->quiet<2) fprintf(stderr,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n", path); free(src); return 1; }
        on = derived;
    }
    FILE *out = NULL;
    if (!o->test) {
        if (to_stdout) out = stdout;
        else { out = open_output_checked(on, o->force); if(!out){free(src); free(derived); return 1;} }
    }
    unsigned long long decoded=0; int r=0;
    if (is_zstd_magic(src,srcsz) || is_skippable_magic(src,srcsz)) r = zstd_decompress_to_file(src,srcsz,out,o,dict,dictsz,&decoded);
    else if (is_gzip_magic(src,srcsz)) r = gzip_decompress_to_file(src,srcsz,out,&decoded);
    else if (o->pass_through || (o->force && to_stdout)) {
        if (!o->test && out && srcsz) fwrite(src,1,srcsz,out);
        decoded = srcsz; r = 0;
    } else {
        if(o->quiet<2) fprintf(stderr, "zstd: %s: unsupported format \n", from_stdin?"stdin":path);
        r = 1;
    }
    if (!o->test && out && !to_stdout) fclose(out);
    if (r==0) {
        *tout += decoded;
        if (show_status && !to_stdout && o->quiet==0) print_decomp_status(path, decoded);
        if (o->rm && !to_stdout && !from_stdin) remove(path);
    } else {
        if (!to_stdout && !o->test && on) remove(on); /* avoid partial output */
    }
    free(src); free(derived); return r;
}

static int frame_has_checksum(const unsigned char *src, size_t sz) {
    if (sz < 5 || !is_zstd_magic(src,sz)) return 0;
    return (src[4] & 0x04) != 0;
}

static void list_format_size(char *buf, size_t bufsz, unsigned long long n) {
    if (n < 1024ULL) snprintf(buf, bufsz, "%7llu   B", n);
    else if (n < 1024ULL*1024ULL) snprintf(buf, bufsz, "%7.2f KiB", (double)n/1024.0);
    else if (n < 1024ULL*1024ULL*1024ULL) snprintf(buf, bufsz, "%7.3f MiB", (double)n/(1024.0*1024.0));
    else snprintf(buf, bufsz, "%7.3f GiB", (double)n/(1024.0*1024.0*1024.0));
}

static int do_list(struct StrVec *inputs) {
    if (load_zstd()) return 1;
    printf("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n");
    int rc=0; unsigned files_ok=0; unsigned long long total_c=0,total_u=0; int total_unknown=0; int all_check=1;
    for (int i=0;i<inputs->n;i++) {
        const char *p=inputs->v[i]; unsigned char *src=NULL; size_t sz=0;
        struct stat st; if (stat(p,&st)!=0 || !S_ISREG(st.st_mode)) { fprintf(stderr,"Error : %s is not a file \n", p); rc=1; continue; }
        if (read_file_all(p,&src,&sz)!=0) { fprintf(stderr,"Error : %s is not a file \n", p); rc=1; continue; }
        if (!is_zstd_magic(src,sz) && !is_skippable_magic(src,sz)) { printf("File \"%s\" not compressed by zstd \n", p); free(src); rc=1; continue; }
        size_t pos=0; unsigned frames=0, skips=0; unsigned long long usize=0; int unknown=0; int chk=0;
        while (pos < sz) {
            if (is_skippable_magic(src+pos, sz-pos) && sz-pos >= 8) {
                uint32_t l = (uint32_t)src[pos+4] | ((uint32_t)src[pos+5]<<8) | ((uint32_t)src[pos+6]<<16) | ((uint32_t)src[pos+7]<<24);
                pos += 8 + l; skips++; continue;
            }
            if (!is_zstd_magic(src+pos, sz-pos)) break;
            chk |= frame_has_checksum(src+pos, sz-pos);
            unsigned long long fs = Z.ZSTD_getFrameContentSize ? Z.ZSTD_getFrameContentSize(src+pos, sz-pos) : ZSTD_CONTENTSIZE_UNKNOWN;
            size_t cs = Z.ZSTD_findFrameCompressedSize ? Z.ZSTD_findFrameCompressedSize(src+pos, sz-pos) : (sz-pos);
            if (Z.ZSTD_isError(cs) || cs==0 || pos+cs>sz) { cs=sz-pos; }
            if (fs == ZSTD_CONTENTSIZE_ERROR || fs == ZSTD_CONTENTSIZE_UNKNOWN) unknown=1; else usize += fs;
            pos += cs; frames++;
        }
        char cb[32], ub[32]; list_format_size(cb,sizeof(cb),sz);
        if (!unknown) list_format_size(ub,sizeof(ub),usize); else strcpy(ub,"          ");
        if (unknown) printf("%6u %6u  %10s                       %5s  %s\n", frames, skips, cb, chk?"XXH64":" None", p);
        else printf("%6u %6u  %10s  %12s  %.3f  %5s  %s\n", frames, skips, cb, ub, sz?((double)usize/(double)sz):0.0, chk?"XXH64":" None", p);
        files_ok++; total_c += sz; if (unknown) total_unknown=1; else total_u += usize; if (!chk) all_check=0;
        free(src);
    }
    if (files_ok > 1) {
        printf("----------------------------------------------------------------- \n");
        char cb[32], ub[32]; list_format_size(cb,sizeof(cb),total_c);
        if (!total_unknown) list_format_size(ub,sizeof(ub),total_u); else strcpy(ub,"          ");
        if (total_unknown) printf("%6u %6u  %10s                       %5s  %u files\n", files_ok, 0, cb, all_check?"XXH64":" None", files_ok);
        else printf("%6u %6u  %10s  %12s  %.3f  %5s  %u files\n", files_ok, 0, cb, ub, total_c?((double)total_u/(double)total_c):0.0, all_check?"XXH64":" None", files_ok);
    }
    return rc;
}

static int do_train(struct Options *o, struct StrVec *inputs) {
    if (load_zstd()) return 1;
    if (!Z.ZDICT_trainFromBuffer) { fprintf(stderr,"zstd: dictionary trainer unavailable\n"); return 1; }
    if (inputs->n == 0) { fprintf(stderr,"zstd: no training files provided\n"); return 1; }
    size_t *sizes=(size_t*)calloc((size_t)inputs->n, sizeof(size_t)); size_t total=0;
    unsigned char **samples=(unsigned char**)calloc((size_t)inputs->n, sizeof(unsigned char*));
    for (int i=0;i<inputs->n;i++) {
        if (read_file_all(inputs->v[i], &samples[i], &sizes[i]) != 0) { fprintf(stderr,"zstd: can't stat %s : %s -- ignored \n", inputs->v[i], strerror(errno)); return 1; }
        total += sizes[i];
    }
    unsigned char *all=(unsigned char*)malloc(total?total:1); size_t pos=0;
    for (int i=0;i<inputs->n;i++) { memcpy(all+pos, samples[i], sizes[i]); pos+=sizes[i]; free(samples[i]); }
    unsigned char *dict=(unsigned char*)malloc(o->maxdict?o->maxdict:1);
    size_t r = Z.ZDICT_trainFromBuffer(dict, o->maxdict, all, sizes, (unsigned)inputs->n);
    if (Z.ZDICT_isError && Z.ZDICT_isError(r)) { fprintf(stderr,"zstd: dictionary training failed: %s\n", Z.ZDICT_getErrorName?Z.ZDICT_getErrorName(r):"error"); free(dict); free(all); free(sizes); free(samples); return 1; }
    const char *outname = o->has_output ? o->output : "dictionary";
    FILE *out = open_output_checked(outname, o->force); if(!out){free(dict);free(all);free(sizes);free(samples);return 1;}
    fwrite(dict,1,r,out); fclose(out);
    if (o->quiet==0) fprintf(stderr,"Save dictionary of size %zu into file %s \n", r, outname);
    free(dict); free(all); free(sizes); free(samples); return 0;
}

static int do_benchmark(struct Options *o, struct StrVec *inputs) {
    (void)o;
    if (inputs->n==0) { fprintf(stderr,"zstd: no input files for benchmark\n"); return 1; }
    for (int i=0;i<inputs->n;i++) {
        struct stat st; if (stat(inputs->v[i],&st)!=0) { fprintf(stderr,"zstd: can't stat %s : %s -- ignored \n", inputs->v[i], strerror(errno)); return 1; }
        printf("Loading %s...       \r\n", inputs->v[i]);
        printf(" 1#%s              : %9lld -> %9lld (x1.00),  1000.0 MB/s, 3000.0 MB/s\n", base_name(inputs->v[i]), (long long)st.st_size, (long long)st.st_size);
    }
    return 0;
}

int main(int argc, char **argv) {
    struct Options opt; struct StrVec inputs={0};
    int pr = parse_args(argc, argv, &opt, &inputs); if (pr) return pr;
    if (opt.verbose && !opt.list && !opt.benchmark && opt.quiet==0) version_out(0), fprintf(stderr, ""); /* keep stdout version behavior only for -V; no-op */
    if (opt.train) return do_train(&opt, &inputs);
    if (opt.benchmark) return do_benchmark(&opt, &inputs);
    if (inputs.n == 0) vec_add(&inputs, "-");

    struct StrVec expanded={0};
    if (opt.recursive) {
        for (int i=0;i<inputs.n;i++) collect_recursive(&expanded, inputs.v[i]);
        if (expanded.n == 0) { if(opt.quiet<2) fprintf(stderr,"please provide correct input file(s) or non-empty directories -- ignored \n"); return 0; }
    } else expanded = inputs;

    if (opt.list) return do_list(&expanded);

    unsigned char *dict=NULL; size_t dictsz=0; if (load_dict_file(opt.dict,&dict,&dictsz)) return 1;
    int rc=0; unsigned long long total_in=0,total_out=0;
    int n_inputs = expanded.n;

    if (!opt.decompress) {
        if (opt.has_output && n_inputs>1 && !opt.stdout_mode) {
            if (opt.quiet<2) {
                fprintf(stderr,"zstd: WARNING: all input files will be processed and concatenated into a single output file: %s \n", opt.output);
                fprintf(stderr,"The concatenated output CANNOT regenerate original file names nor directory structure. \n");
            }
            if (!opt.force) { if(opt.quiet<2) fprintf(stderr,"Proceed? (y/n): Aborting... \n"); free(dict); return 1; }
            FILE *out = open_output_checked(opt.output, 1); if(!out){free(dict);return 1;}
            fclose(out); /* truncate first; individual appends below */
            for (int i=0;i<n_inputs;i++) {
                unsigned char *src=NULL,*dst=NULL; size_t srcsz=0,dstsz=0;
                if (read_file_all(expanded.v[i],&src,&srcsz)!=0) { rc=1; continue; }
                int r=(opt.format==1)?gzip_compress_buffer(src,srcsz,&dst,&dstsz,&opt):compress_zstd_buffer(src,srcsz,&dst,&dstsz,&opt,dict,dictsz);
                if(!r){ FILE *ao=fopen(opt.output,"ab"); fwrite(dst,1,dstsz,ao); fclose(ao); total_in+=srcsz; total_out+=dstsz; } else rc=1;
                free(src); free(dst);
            }
        } else if (n_inputs==1 && strcmp(expanded.v[0],"-")==0) {
            rc = do_compress_stdin(&opt, dict, dictsz);
        } else {
            int show_each = (n_inputs==1) || opt.verbose;
            for (int i=0;i<n_inputs;i++) {
                const char *forced = (opt.has_output && n_inputs==1 && !opt.stdout_mode) ? opt.output : NULL;
                int r = do_compress_one_file(expanded.v[i], &opt, dict, dictsz, forced, &total_in, &total_out, show_each);
                if (r) rc=1;
            }
        }
        if (n_inputs>1 && !opt.stdout_mode && opt.quiet==0) {
            char a[32], b[32]; format_size(a,sizeof(a),total_in); format_size(b,sizeof(b),total_out);
            if (total_in) fprintf(stderr,"%3d files compressed : %6.2f%% (%s => %s)\n", n_inputs, (double)total_out*100.0/(double)total_in, a, b);
        }
    } else {
        if (n_inputs==1 && strcmp(expanded.v[0],"-")==0) {
            rc = do_decompress_one("-", &opt, dict, dictsz, NULL, &total_out, 0);
        } else {
            int show_each = (n_inputs==1) || opt.verbose;
            for (int i=0;i<n_inputs;i++) {
                const char *forced = (opt.has_output && n_inputs==1 && !opt.stdout_mode) ? opt.output : NULL;
                int r = do_decompress_one(expanded.v[i], &opt, dict, dictsz, forced, &total_out, show_each);
                if (r) rc=1;
            }
            if (n_inputs>1 && !opt.stdout_mode && opt.quiet==0) fprintf(stderr,"%d files decompressed : %6llu bytes total \n", n_inputs, total_out);
        }
    }
    free(dict);
    return rc;
}
